`,topics:String.raw`var TOPICS=[{"id": "roofs", "t": "Roof work, fragile surfaces and edge protection", "p": ["Any fall from height can kill. Roof access is planned and set out in the RAMS before anyone goes up.", "Check the edge protection, netting and access points are in place and inspected before you start.", "Treat every rooflight and any unknown roof sheet as fragile. Never step on them; use crawling boards or stay on the designated walkways.", "Remove sheets in small, controlled sections so the roof stays stable, and report any damaged purlins or fixings straight away.", "Keep an exclusion zone below the work and tether tools so nothing falls on people below.", "Stop work in high wind (above 23 mph), rain, ice or poor light. Nobody works on a roof alone."]}, {"id": "ladders", "t": "Ladders and stepladders", "p": ["Use ladders only for short-duration, light work (minutes, not hours) where a platform or MEWP isn't practicable.", "Do a pre-use check: feet, rungs, stiles and locks. Use Class 1 or EN 131 professional ladders only.", "Set leaning ladders at about 1 out for every 4 up, on firm level ground, extending 1 m above the landing point.", "Tie the ladder or have it footed. Keep three points of contact and don't overreach.", "Don't carry heavy or awkward items up a ladder. Use a hoist or lifting equipment."]}, {"id": "mewp", "t": "MEWPs and telehandlers", "p": ["Only trained, carded operators (IPAF or CPCS/NPORS) may operate a MEWP or telehandler.", "Do the pre-use check and check the thorough examination (LOLER) is in date.", "Check the ground conditions, overhead hazards and the exclusion zone before setting up.", "Wear a harness with a short restraint lanyard in boom-type MEWPs, clipped to the designated anchor.", "A trained ground rescue person stays at ground level while the MEWP is in use and knows how to use the ground controls.", "A banksman controls every telehandler movement near people or in the client's yard."]}, {"id": "dust", "t": "Dust and silica", "p": ["Cutting, drilling and grinding concrete, brick, block or stone creates silica dust, which causes lung disease.", "Use on-tool extraction (M or H class) or water suppression every time.", "Wear face-fit tested RPE (FFP3 as a minimum for silica). Be clean-shaven where the mask seals.", "Never dry sweep or blow dust with compressed air. Use an H-class vacuum.", "Keep the client's areas, especially food production areas, sealed off from dust."]}, {"id": "asbestos", "t": "Asbestos awareness", "p": ["Buildings built or refurbished before 2000 may contain asbestos: roof sheets, cladding, insulation board, pipe lagging, textured coatings and floor tiles.", "Check the client's asbestos survey before work starts and ask the site manager if you are unsure.", "If you find something you suspect is asbestos: stop, do not disturb it, keep others away and tell the site manager.", "Only a licensed or competent specialist removes asbestos. Breathing in the fibres causes fatal diseases years later."]}, {"id": "hotworks", "t": "Hot works and fire risk", "p": ["Grinding, cutting and welding throw sparks that can start fires hours later.", "Hot works only go ahead under a CBS hot works permit, with the client's approval where required.", "Clear or protect combustibles, check what is behind and below the work, and keep a suitable extinguisher at hand.", "Keep a fire watch during the work and for at least 60 minutes afterwards, then check the area again before leaving."]}, {"id": "livesite", "t": "Working on live client sites and food factories", "p": ["We work in live premises. Follow the client's site rules, sign in and out, and stay within the segregated work area.", "Food sites: no food, drink, glass or loose items in production areas, follow the client's hygiene and PPE rules, and report any foreign body risk.", "Keep barriers, signage and segregation in place at all times. Never use the client's equipment without permission.", "Keep vehicle movements to agreed times and routes, with a banksman in the client's yard.", "Leave nothing behind: no debris, fixings, packaging or tools at height or on the client's premises at the end of the shift."]}, {"id": "lifting", "t": "Manual handling", "p": ["Avoid manual handling where you can by using the telehandler, trolleys or other aids.", "Plan the lift: check the weight, route and where it's going. Team lift long or awkward items such as roof sheets.", "Lift with your legs, keep the load close and don't twist.", "Wear gloves when handling sheets: edges are sharp. Take extra care in wind."]}, {"id": "tools", "t": "Power tools and electrical safety", "p": ["Use 110 V or battery tools on site. Check tools and leads before use and make sure they've been inspected.", "Guards on, the correct disc or blade for the material, and never remove guards.", "Keep leads out of walkways and away from water and sharp edges.", "Wear eye and hearing protection, plus RPE and gloves as the RAMS require.", "Disconnect before changing discs or blades. Never leave a tool running unattended."]}, {"id": "vehicles", "t": "Vehicles and load security", "p": ["Do the daily vehicle check. Report defects and don't drive a vehicle that isn't safe.", "Secure every load. Sheets, ladders and materials must be strapped, not just packed in.", "No handheld phone use while driving. Pull over safely.", "Plan breaks on long drives and watch for fatigue."]}, {"id": "weather", "t": "Weather, heat and cold", "p": ["Check the forecast and wind speed before roof work. Stop when conditions turn.", "In summer: sun protection, water and shade breaks.", "In cold or wet weather, watch for ice, frost and slippery surfaces, and keep warm and dry.", "Anyone can stop work because of the weather. Nobody will be criticised for it."]}, {"id": "ppe", "t": "PPE: what and when", "p": ["PPE is the last line of defence, but it is required on every job.", "Safety boots, hi-vis, hard hat and gloves as standard. Eye, hearing and respiratory protection and harnesses as the RAMS require.", "Check PPE before use and replace anything damaged. Ask the office through the team app.", "RPE only works if it fits. Face-fit test, and do a fit check every time you put it on."]}, {"id": "reporting", "t": "Reporting accidents, incidents and near misses", "p": ["Report every accident, injury and near miss, however small, to the site manager and in the CBS team app.", "Near misses show us where the next injury will come from. Reporting them prevents harm.", "Serious injuries and dangerous occurrences may be reportable to HSE under RIDDOR. Tell the site manager immediately.", "Nobody gets in trouble for reporting. Not reporting is the problem."]}, {"id": "emergency", "t": "First aid and emergencies", "p": ["Know where the first aid kit, fire extinguisher and assembly point are, and who the first aiders are.", "Know the site address and postcode so you can give them to 999.", "Know the nearest A&E for today's job.", "For non-urgent medical advice, call NHS 111. For anything serious, call 999."]}];
